import socket
from contextlib import contextmanager

import paramiko
import paramiko.common
from paramiko.channel import Channel


def try_method_none(
    logger,
    log_channel,
    ssh_client,
    hostname,
    port,
    username,
    timeout,
    sock=None,
    **_,
):
    """
    Try to authenticate with method-none, return True on success, False
    otherwise.

    Pass the transport created in the process into given paramiko.SSHClient.
    """
    logger.info("Trying method-none authentiaction first.")

    # If we got a socket here, its probably a ParaProxy object.
    if sock is None:
        sock = socket.create_connection((hostname, port), timeout)
    transport = paramiko.Transport(sock)
    if log_channel is not None:
        transport.set_log_channel(log_channel)
    transport.start_client(timeout=timeout)
    try:
        transport.auth_none(username)
    except paramiko.BadAuthenticationType as exc:
        transport.close()
        sock.close()

        logger.info("Server does not accept method-none.")
        logger.debug("Raised while trying method-none: %r", exc)
        logger.info("Authentication methods that can continue: %s", exc.allowed_types)
        return False
    except Exception:
        logger.exception("Failure during method-none authorization - bad response?")
        transport.close()
        sock.close()
        raise

    ssh_client._transport = transport
    return True


@contextmanager
def set_default_open_session_timeout(transport, timeout):
    """Set a default timeout for a paramiko.Transport.open_session argument.

    Use this as a context manager. After exiting, the default timeout will be
    restored.

    For some inexplicable reason nobody exposes this parameter. Not even
    paramiko, in case of SFTPClient...

    *Sigh*
    """
    # The signature for open_session is:
    # self, window_size=None, max_packet_size=None, timeout=None
    old_defaults = transport.open_session.__func__.__defaults__
    transport.open_session.__func__.__defaults__ = (None, None, timeout)

    try:
        yield
    finally:
        transport.open_session.__func__.__defaults__ = old_defaults


def send_signal(
    channel: paramiko.Channel,
    signal: str,
):
    """
    Send signal to the process that was opened via exec_command.

    Some SSH servers may have not implemented this feature, in which case
    the signal request is ignored.

    :param str signal: name of the signal to send. Possible values include:
        "ABRT", "ALRM", "FPE", "HUP", "ILL", "INT", "KILL", "PIPE", "QUIT",
        "SEGV", "TERM", "USR1", "USR2".
    :param paramiko.Channel channel: process channel to send the signal to.
    """
    m = paramiko.message.Message()
    m.add_byte(paramiko.common.cMSG_CHANNEL_REQUEST)
    m.add_int(channel.remote_chanid)
    m.add_string("signal")
    m.add_boolean(False)
    m.add_string(signal)
    channel.transport._send_user_message(m)


# Add default values to the Channel class so that callers can read them even if
# there's no exit signal (see handle_exit_signal below)
Channel.exit_signal = None  # type: ignore
Channel.core_dumped = None  # type: ignore
Channel.signal_message = None  # type: ignore
Channel.language_tag = None  # type: ignore


def _extended_request_handler(channel: paramiko.Channel, message: paramiko.Message):
    # Ensure we don't clobber the underlying BytesIO buffer
    message_copy = paramiko.Message(message.asbytes())

    message_copy.get_int()  # Channel id. Unused, read to move the buffer
    key = message_copy.get_text()
    if key == "exit-signal":
        message_copy.get_boolean()  # 'want reply' - never used for this request
        channel.exit_signal = message_copy.get_string()  # type: ignore
        channel.core_dumped = message_copy.get_boolean()  # type: ignore
        channel.signal_message = message_copy.get_string()  # type: ignore
        channel.language_tag = message_copy.get_string()  # type: ignore
        channel.status_event.set()
    else:
        # All versions of paramiko that work on 3.9+ have this method. As
        # of writing this, the latest paramiko version is 3.5.1
        Channel._handle_request(channel, message)  # type: ignore


def handle_exit_signal(transport: paramiko.Transport):
    """
    Make the channel request handler handle "exit-signal" requests (RFC 4254).

    Extends current handler to write the data given by the server within the
    exit-signal channel request into the Channel's status attributes.

    If the remote process gets closed by a signal, and the remote server
    supports this class of channel requests, it will most likely result in the
    exit_status being set to `int(-1)` (since that's a default for Paramiko
    when it doesn't get the EC).

    It only makes sense if one channel request type of the two (exit-status,
    exit-signal) gets sent by the server. They are exclusive alternatives on
    POSIX. You should never get both. (You can however get none, if the server
    doesn't support them).

    The results of these requests are stored within the channel's attributes.
    """
    handler_table = transport._channel_handler_table  # type: ignore
    handler_table[paramiko.common.MSG_CHANNEL_REQUEST] = _extended_request_handler
